 "content": "from collections import deque


def transform(grid):
    """Erase the 4-connected nonzero object containing the fewest 9s."""
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            components.append(comp)
    if not components:
        return [row[:] for row in grid]
    erased = min(components, key=lambda comp: sum(grid[r][c] == 9 for r, c in comp))
    out = [row[:] for row in grid]
    for r, c in erased:
        out[r][c] = 0
    return out
